@push('scripts')<script>const materials=@json($materials->map(fn($m)=>['id'=>$m->id,'label'=>$m->material_code.' - '.$m->name])->values());document.getElementById('add-transfer-item').onclick=function(){const c=document.getElementById('transfer-items'),i=c.querySelectorAll('.transfer-item').length,o=materials.map(m=>`<option value="${m.id}">${m.label}</option>`).join('');c.insertAdjacentHTML('beforeend',`<div class="transfer-item form-group row"><div class="col-md-7"><select name="items[${i}][material_id]" class="form-control" required><option value="">Select Material</option>${o}</select></div><div class="col-md-4"><input type="number" name="items[${i}][quantity]" class="form-control" min="0.001" step="0.001" placeholder="Quantity" required></div><div class="col-md-1"><button type="button" class="btn btn-danger remove-transfer-item">&times;</button></div></div>`);};document.getElementById('transfer-items').onclick=function(e){if(e.target.classList.contains('remove-transfer-item')&&document.querySelectorAll('.transfer-item').length>1)e.target.closest('.transfer-item').remove();};</script>@endpush
